<script lang="ts">
  import { t as uiText, locale } from './i18n.js';
  import { onMount } from 'svelte';
  interface Template {file:string;name:string;version:string;nodeCount:number;assetCount:number;preview?:string;features?:Record<string,boolean>;gameCodes?:string[];notes?:string;error?:string}
  interface Props {onopen:(bytes:ArrayBuffer,file:string)=>Promise<void>;onclose:()=>void}
  let {onopen,onclose}:Props=$props();
  let catalog=$state<Template[]>([]),error=$state(''),busy=$state('');
  onMount(async()=>{try{const r=await fetch('/api/templates?language='+$locale);if(!r.ok)throw Error($uiText("Không đọc được thư mục templete."));catalog=await r.json();}catch(e){error=e instanceof Error?e.message:String(e);}});
  async function open(file:string){busy=file;try{const r=await fetch('/api/templates?file='+encodeURIComponent(file));if(!r.ok)throw Error($uiText("Không mở được ZIP mẫu."));await onopen(await r.arrayBuffer(),file);onclose();}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy='';}}
</script>
<div class="modal-backdrop"><div class="modal template-modal" role="dialog" aria-modal="true" aria-label={$uiText("Thư viện mẫu companion")} tabindex="-1"><div class="modal-title"><h2>{$uiText("Thư viện mẫu companion")}</h2><button onclick={onclose}>✕</button></div><p>{$uiText("Mở bản sao để chỉnh sửa. Các ZIP gốc trong thư mục templete được giữ nguyên.")}</p><p class="muted">{$uiText("Xem trước bằng dữ liệu mẫu; studio không chạy Lua. Thông tin chưa kiểm chứng trên thiết bị được giữ trong ghi chú của mẫu.")}</p>{#if error}<p class="error">{$uiText(error)}</p>{/if}<div class="template-grid">{#each catalog as pack}<article>{#if pack.preview}<img src={pack.preview} alt={$uiText("Nền {0}", pack.name)} />{/if}<h3>{pack.name}</h3><p>v{pack.version} · {pack.nodeCount} {$uiText("nút ·")} {pack.assetCount} {$uiText("tài nguyên")}</p><div class="feature-tags">{#each [['tabs','Tab'],['pages','Trang'],['lists',$uiText("Danh sách lặp")],['conditions',$uiText("Điều kiện")],['boundStyles',$uiText("Style động")]] as [key,label]}{#if pack.features?.[key]}<span>{label}</span>{/if}{/each}</div><p class="muted">{pack.gameCodes?.join(' · ')}</p>{#if pack.notes}<details><summary>{$uiText("Ghi chú gốc & giới hạn kiểm chứng")}</summary><pre>{pack.notes}</pre></details>{/if}<button class="primary" disabled={!!busy||!!pack.error} onclick={()=>open(pack.file)}>{busy===pack.file?$uiText("Đang mở…"):$uiText("Mở bản sao")}</button>{#if pack.error}<p class="error">{pack.error}</p>{/if}</article>{/each}</div>{#if !catalog.length&&!error}<p>{$uiText("Đang đọc các mẫu…")}</p>{/if}</div></div>
<style>.template-modal{width:940px}.template-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.template-grid article{background:#242f40;border:1px solid #495d76;border-radius:6px;padding:14px}.template-grid img{width:100%;height:110px;object-fit:cover;border-radius:4px}.template-grid h3{font-size:14px}.template-grid article>p{font-size:11px}.feature-tags{display:flex;gap:5px;flex-wrap:wrap}.feature-tags span{padding:3px 6px;background:#3b516c;color:#c8e5ff;border-radius:4px;font-size:10px}.template-grid summary{font-size:11px;cursor:pointer;margin-bottom:9px}.template-grid pre{white-space:pre-wrap;font:11px/1.5 monospace;max-height:180px;overflow:auto}.template-grid .primary{margin-top:8px}</style>
